import java.util.*;

class Solution {
    public boolean hasZeroSumSubarray(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        int sum = 0;
        seen.add(0);
        for (int value : nums) {
            sum += value;
            if (seen.contains(sum)) return true;
            seen.add(sum);
        }
        return false;
    }
}
